2384	        const int row = row_base + lane / 8;
2385	        const int col = (lane % 8) * 4;
2386	        const float4 values = make_float4(
2387	            tile[row * LD + col],
2388	            tile[row * LD + col + 1],
2389	            tile[row * LD + col + 2],
2390	            tile[row * LD + col + 3]
2391	        );
2392	        *reinterpret_cast<float4*>(dst + row * N + col) = values;
2393	    }
2394	}
