2396	template <int K>
2397	__device__ __forceinline__ void register_cholesky_step_64(
2398	    float (&row_values)[64],
2399	    float* tile,
2400	    float* inverse,
2401	    int group,
2402	    int lane,
2403	    bool active
2404	) {
2405	    constexpr int LD = 65;
2406	    float value = 0.0f;
2407	    if (active && lane >= K) {
2408	        value = row_values[K];
2409	        #pragma unroll
2410	        for (int j = 0; j < K; ++j) {
2411	            value = fmaf(-row_values[j], tile[K * LD + j], value);
2412	        }
2413	    }
2414	
2415	    if (active && lane == K) {
2416	        const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
2417	        row_values[K] = diagonal;
2418	        tile[K * LD + K] = diagonal;
2419	        inverse[group] = 1.0f / diagonal;
2420	    }
2421	    __syncthreads();
2422	
2423	    if (active && lane > K) {
2424	        value *= inverse[group];
2425	        row_values[K] = value;
2426	        tile[lane * LD + K] = value;
2427	    }
2428	    __syncthreads();
2429	
2430	    if constexpr (K + 1 < 64) {
2431	        register_cholesky_step_64<K + 1>(
2432	            row_values, tile, inverse, group, lane, active
2433	        );
2434	    }
2435	}
