2437	__global__ void grouped_two_cholesky_64(
2438	    const float* __restrict__ input,
2439	    float* __restrict__ output,
2440	    int batch
2441	) {
2442	    constexpr int N = 64;
2443	    constexpr int LD = 65;
2444	    constexpr int MATRICES_PER_BLOCK = 2;
2445	    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
2446	    __shared__ float inverse[MATRICES_PER_BLOCK];
2447	    const int group = threadIdx.x / N;
2448	    const int lane = threadIdx.x % N;
2449	    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + group;
2450	    const bool active = matrix < batch;
2451	    float* tile = storage + group * N * LD;
2452	
2453	    if (active) {
2454	        const long long base = static_cast<long long>(matrix) * N * N;
2455	        const float* src = input + base;
2456	        #pragma unroll
2457	        for (int row = 0; row < N; ++row) {
2458	            tile[row * LD + lane] = row >= lane
2459	                ? src[row * N + lane]
2460	                : 0.0f;
2461	        }
2462	    }
2463	    __syncthreads();
2464	
2465	    float row_values[N];
2466	    #pragma unroll
2467	    for (int col = 0; col < N; ++col) {
2468	        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
2469	    }
2470	    register_cholesky_step_64<0>(
2471	        row_values, tile, inverse, group, lane, active
2472	    );
2473	
2474	    if (active) {
2475	        const long long base = static_cast<long long>(matrix) * N * N;
2476	        float* dst = output + base;
2477	        #pragma unroll
2478	        for (int row = 0; row < N; ++row) {
2479	            dst[row * N + lane] = tile[row * LD + lane];
2480	        }
2481	    }
2482	}
