2484	__device__ __forceinline__ void n128_group_sync() {
2485	    if (threadIdx.x < 448) {
2486	        asm volatile("bar.sync 1, 448;" ::: "memory");
2487	    } else {
2488	        asm volatile("bar.sync 2, 448;" ::: "memory");
2489	    }
2490	}
