2499	__device__ __forceinline__ void factor_panel_16_warp(
2500	    float* tile,
2501	    int panel,
2502	    int local_tid
2503	) {
2504	    const int lane = local_tid % 32;
2505	    const int panel_block = panel / 16;
2506	    float* diagonal = tile + n128_block_tile_offset(
2507	        panel_block, panel_block
2508	    );
2509	    if (lane < 16) {
2510	        float row_values[16];
2511	        #pragma unroll
2512	        for (int col = 0; col < 16; ++col) {
2513	            row_values[col] = lane >= col
2514	                ? diagonal[lane * 16 + col]
2515	                : 0.0f;
2516	        }
2517	
2518	        #pragma unroll
2519	        for (int pivot = 0; pivot < 16; ++pivot) {
2520	            float value = row_values[pivot];
2521	            #pragma unroll
2522	            for (int col = 0; col < pivot; ++col) {
2523	                const float pivot_value = __shfl_sync(
2524	                    0x0000ffff, row_values[col], pivot, 16
2525	                );
2526	                if (lane >= pivot) {
2527	                    value = fmaf(-row_values[col], pivot_value, value);
2528	                }
2529	            }
2530	            float inverse = 0.0f;
2531	            if (lane == pivot) {
2532	                const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
2533	                row_values[pivot] = diagonal;
2534	                inverse = 1.0f / diagonal;
2535	            }
2536	            inverse = __shfl_sync(0x0000ffff, inverse, pivot, 16);
2537	            if (lane > pivot) {
2538	                row_values[pivot] = value * inverse;
2539	            }
2540	        }
2541	
2542	        #pragma unroll
2543	        for (int col = 0; col < 16; ++col) {
2544	            if (lane >= col) {
2545	                diagonal[lane * 16 + col] = row_values[col];
2546	            }
2547	        }
2548	    }
2549	}
