2551	__device__ __forceinline__ void factor_panel_16(
2552	    float* tile,
2553	    int panel,
2554	    int local_tid,
2555	    bool matrix_active
2556	) {
2557	    if (matrix_active && local_tid / 32 == 0) {
2558	        factor_panel_16_warp(tile, panel, local_tid);
2559	    }
2560	    n128_group_sync();
2561	}
