2563	__device__ __forceinline__ void solve_panel_16(
2564	    float* tile,
2565	    int panel,
2566	    int local_tid,
2567	    bool matrix_active
2568	) {
2569	    constexpr int N = 128;
2570	    constexpr int TEAM_WIDTH = 4;
2571	    const int team = local_tid / TEAM_WIDTH;
2572	    const int lane = local_tid % TEAM_WIDTH;
2573	    const int stop = panel + 16;
2574	    const int row = stop + team;
2575	    if (matrix_active) {
2576	        const bool row_active = row < N;
2577	        const int panel_block = panel / 16;
2578	        float* diagonal = tile + n128_block_tile_offset(
2579	            panel_block, panel_block
2580	        );
2581	        float* panel_tile = row_active
2582	            ? tile + n128_block_tile_offset(row / 16, panel_block)
2583	            : tile;
2584	        const int local_row = row % 16;
2585	        float row_values[4];
2586	        #pragma unroll
2587	        for (int item = 0; item < 4; ++item) {
2588	            row_values[item] = row_active
2589	                ? panel_tile[
2590	                    local_row * 16 + item * TEAM_WIDTH + lane
2591	                ]
2592	                : 0.0f;
2593	        }
2594	        #pragma unroll
2595	        for (int pivot = 0; pivot < 16; ++pivot) {
2596	            float dot = 0.0f;
2597	            #pragma unroll
2598	            for (int item = 0; item < 4; ++item) {
2599	                const int col = item * TEAM_WIDTH + lane;
2600	                if (col < pivot) {
2601	                    dot = fmaf(
2602	                        row_values[item],
2603	                        diagonal[pivot * 16 + col],
2604	                        dot
2605	                    );
2606	                }
2607	            }
2608	            dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
2609	            dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
2610	            float original = __shfl_sync(
2611	                0xffffffff,
2612	                row_values[pivot / TEAM_WIDTH],
2613	                pivot % TEAM_WIDTH,
2614	                TEAM_WIDTH
2615	            );
2616	            float solved = lane == 0
2617	                ? (original - dot)
2618	                    / diagonal[pivot * 16 + pivot]
2619	                : 0.0f;
2620	            solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
2621	            if (lane == pivot % TEAM_WIDTH) {
2622	                row_values[pivot / TEAM_WIDTH] = solved;
2623	            }
2624	        }
2625	        if (row_active) {
2626	            #pragma unroll
2627	            for (int item = 0; item < 4; ++item) {
2628	                panel_tile[
2629	                    local_row * 16 + item * TEAM_WIDTH + lane
2630	                ] =
2631	                    row_values[item];
2632	            }
2633	        }
2634	    }
2635	    n128_group_sync();
2636	}
