2638	__device__ __forceinline__ void compensated_rankk_16(
2639	    float* tile,
2640	    int panel,
2641	    int local_tid,
2642	    bool matrix_active
2643	) {
2644	    constexpr int N = 128;
2645	    constexpr int WARPS = 14;
2646	    constexpr int MMA_M = 16;
2647	    constexpr int MMA_N = 16;
2648	    constexpr int MMA_K = 8;
2649	    constexpr float RESIDUAL_SCALE = 32.0f;
2650	    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
2651	    const int warp = local_tid / 32;
2652	    const int stop = panel + 16;
2653	    const int tile_count = (N - stop) / MMA_M;
2654	    const int panel_block = panel / MMA_M;
2655	    const int stop_block = stop / MMA_M;
2656	    if (matrix_active) {
2657	        int ordinal = 0;
2658	        for (int block_row = 0; block_row < tile_count; ++block_row) {
2659	            for (int block_col = 0; block_col <= block_row; ++block_col) {
2660	                if (ordinal % WARPS == warp) {
2661	                    {
2662	                wmma::fragment<
2663	                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
2664	                    wmma::precision::tf32, wmma::row_major
2665	                > a_high;
2666	                wmma::fragment<
2667	                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
2668	                    wmma::precision::tf32, wmma::row_major
2669	                > a_scaled;
2670	                wmma::fragment<
2671	                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
2672	                    wmma::precision::tf32, wmma::col_major
2673	                > b_high;
2674	                wmma::fragment<
2675	                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
2676	                    wmma::precision::tf32, wmma::col_major
2677	                > b_scaled;
2678	                wmma::fragment<
2679	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2680	                > high_product;
2681	                wmma::fragment<
2682	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2683	                > scaled_product;
2684	                wmma::fragment<
2685	                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
2686	                > accumulator;
2687	                wmma::fill_fragment(high_product, 0.0f);
2688	                wmma::fill_fragment(scaled_product, 0.0f);
2689	                #pragma unroll
2690	                for (int offset = 0; offset < 16; offset += MMA_K) {
2691	                    wmma::load_matrix_sync(
2692	                        a_high,
2693	                        tile + n128_block_tile_offset(
2694	                            stop_block + block_row, panel_block
2695	                        ) + offset,
2696	                        MMA_M
2697	                    );
2698	                    wmma::load_matrix_sync(
2699	                        b_high,
2700	                        tile + n128_block_tile_offset(
2701	                            stop_block + block_col, panel_block
2702	                        ) + offset,
2703	                        MMA_N
2704	                    );
2705	                    #pragma unroll
2706	                    for (int element = 0;
2707	                         element < a_high.num_elements;
2708	                         ++element) {
2709	                        const float original = a_high.x[element];
2710	                        const float high = wmma::__float_to_tf32(original);
2711	                        a_high.x[element] = high;
2712	                        a_scaled.x[element] = wmma::__float_to_tf32(
2713	                            fmaf(RESIDUAL_SCALE, original - high, high)
2714	                        );
2715	                    }
2716	                    #pragma unroll
2717	                    for (int element = 0;
2718	                         element < b_high.num_elements;
2719	                         ++element) {
2720	                        const float original = b_high.x[element];
2721	                        const float high = wmma::__float_to_tf32(original);
2722	                        b_high.x[element] = high;
2723	                        b_scaled.x[element] = wmma::__float_to_tf32(
2724	                            fmaf(RESIDUAL_SCALE, original - high, high)
2725	                        );
2726	                    }
2727	                    wmma::mma_sync(
2728	                        high_product, a_high, b_high, high_product
2729	                    );
2730	                    wmma::mma_sync(
2731	                        scaled_product,
2732	                        a_scaled,
2733	                        b_scaled,
2734	                        scaled_product
2735	                    );
2736	                }
2737	                wmma::load_matrix_sync(
2738	                    accumulator,
2739	                    tile + n128_block_tile_offset(
2740	                        stop_block + block_row,
2741	                        stop_block + block_col
2742	                    ),
2743	                    MMA_N,
2744	                    wmma::mem_row_major
2745	                );
2746	                #pragma unroll
2747	                for (int element = 0;
2748	                     element < accumulator.num_elements;
2749	                     ++element) {
2750	                    const float correction = (
2751	                        scaled_product.x[element]
2752	                        - high_product.x[element]
2753	                    ) * INVERSE_RESIDUAL_SCALE;
2754	                    accumulator.x[element] -=
2755	                        high_product.x[element] + correction;
2756	                }
2757	                wmma::store_matrix_sync(
2758	                    tile + n128_block_tile_offset(
2759	                        stop_block + block_row,
2760	                        stop_block + block_col
2761	                    ),
2762	                    accumulator,
2763	                    MMA_N,
2764	                    wmma::mem_row_major
2765	                );
2766	                    }
2767	                }
2768	                ++ordinal;
2769	            }
2770	        }
2771	        if (warp == 0) {
2772	            factor_panel_16_warp(tile, stop, local_tid);
2773	        }
2774	    }
2775	    n128_group_sync();
2776	}
