2778	__global__ void blocked_wmma16_cholesky_128(
2779	    const float* __restrict__ input,
2780	    float* __restrict__ output,
2781	    int batch,
2782	    int paired_blocks
2783	) {
2784	    constexpr int N = 128;
2785	    constexpr int THREADS_PER_MATRIX = 448;
2786	    constexpr int MATRICES_PER_BLOCK = 2;
2787	    constexpr int BLOCK_TILE_ELEMENTS = 36 * 16 * 16;
2788	    extern __shared__ float storage[];
2789	    const int group = threadIdx.x / THREADS_PER_MATRIX;
2790	    const int tid = threadIdx.x % THREADS_PER_MATRIX;
2791	    const int block = static_cast<int>(blockIdx.x);
2792	    const int matrix = block < paired_blocks
2793	        ? block * MATRICES_PER_BLOCK + group
2794	        : 2 * paired_blocks + block - paired_blocks
2795	            + (group == 0 ? 0 : batch);
2796	    const bool active = matrix < batch;
2797	    float* tile = storage + group * BLOCK_TILE_ELEMENTS;
2798	    const int base = matrix * N * N;
2799	    const float* src = input + base;
2800	    float* dst = output + base;
2801	    if (active) {
2802	        for (int vector = tid; vector < N * N / 4;
2803	             vector += THREADS_PER_MATRIX) {
2804	            const int row = vector / (N / 4);
2805	            const int col = vector % (N / 4) * 4;
2806	            if (row >= col) {
2807	                float4 values = reinterpret_cast<const float4*>(src)[vector];
2808	                if (row < col + 3) values.w = 0.0f;
2809	                if (row < col + 2) values.z = 0.0f;
2810	                if (row < col + 1) values.y = 0.0f;
2811	                float* packed_tile = tile + n128_block_tile_offset(
2812	                    row / 16, col / 16
2813	                );
2814	                *reinterpret_cast<float4*>(
2815	                    packed_tile + (row % 16) * 16 + col % 16
2816	                ) = values;
2817	            }
2818	        }
2819	    }
2820	    n128_group_sync();
2821	
2822	    factor_panel_16(tile, 0, tid, active);
2823	    #pragma unroll
2824	    for (int panel = 0; panel < N; panel += 16) {
2825	        if (panel + 16 < N) {
2826	            solve_panel_16(tile, panel, tid, active);
2827	            compensated_rankk_16(tile, panel, tid, active);
2828	        }
2829	    }
2830	
2831	    if (active) {
2832	        for (int vector = tid; vector < N * N / 4;
2833	             vector += THREADS_PER_MATRIX) {
2834	            const int row = vector / (N / 4);
2835	            const int col = vector % (N / 4) * 4;
2836	            if (row >= col) {
2837	                const float* packed_tile = tile + n128_block_tile_offset(
2838	                    row / 16, col / 16
2839	                );
2840	                float4 values = *reinterpret_cast<const float4*>(
2841	                    packed_tile + (row % 16) * 16 + col % 16
2842	                );
2843	                if (row < col + 3) values.w = 0.0f;
2844	                if (row < col + 2) values.z = 0.0f;
2845	                if (row < col + 1) values.y = 0.0f;
2846	                reinterpret_cast<float4*>(dst)[vector] = values;
2847	            }
2848	        }
2849	    }
2850	}
