2890	        ? torch::zeros_like(input)
2891	        : torch::empty_like(input);
2892	    if (cache_size < static_cast<int>(cache.size())) {
2893	        cache[cache_size++] = SmallCacheEntry{key, input, output};
2894	    }
2895	    return output;
